def release_metrics(before, after):
    def pct(part, whole):
        if whole == 0:
            return None
        return round(part / whole * 100, 1)

    total = before + after
    return {
        "leakage": pct(after, total),
        "leakage_variant": pct(after, before),
        "dre": pct(before, total),
    }

