from datetime import date

def aging_report(defects, today, limit):
    now = date.fromisoformat(today)
    open_ages = []
    for d in defects:
        if d["closed"] is None:
            age = (now - date.fromisoformat(d["opened"])).days
            open_ages.append((age, d))
    if not open_ages:
        return {"average_open_age": None, "oldest_open": None, "stale_high": []}
    average = round(sum(age for age, _ in open_ages) / len(open_ages), 1)
    oldest = max(open_ages, key=lambda pair: pair[0])[1]["id"]
    stale = [(age, d["id"]) for age, d in open_ages if d["severity"] in ("High", "Critical") and age > limit]
    stale.sort(key=lambda pair: -pair[0])
    return {"average_open_age": average, "oldest_open": oldest, "stale_high": [i for _, i in stale]}
